class Solution {
    using Key = vector<string>;
    using Poly = map<Key, int>;
    string s;
    int pos = 0;
    unordered_map<string, int> values;
    void spaces() { while (pos < (int)s.size() && s[pos] == ' ') ++pos; }
    Poly constant(int x) { return {{Key{}, x}}; }
    Poly add(Poly a, const Poly& b, int sign = 1) {
        for (const auto& p : b) a[p.first] += sign * p.second;
        return a;
    }
    Poly multiply(const Poly& a, const Poly& b) {
        Poly c;
        for (const auto& x : a) for (const auto& y : b) {
            Key key = x.first;
            key.insert(key.end(), y.first.begin(), y.first.end());
            sort(key.begin(), key.end());
            c[key] += x.second * y.second;
        }
        return c;
    }
    Poly factor() {
        spaces();
        if (s[pos] == '(') {
            ++pos;
            Poly p = expression();
            spaces(); ++pos;
            return p;
        }
        if (isdigit(s[pos])) {
            int x = 0;
            while (pos < (int)s.size() && isdigit(s[pos])) x = x * 10 + s[pos++] - '0';
            return constant(x);
        }
        string name;
        while (pos < (int)s.size() && isalpha(s[pos])) name += s[pos++];
        if (values.count(name)) return constant(values[name]);
        return {{Key{name}, 1}};
    }
    Poly term() {
        Poly p = factor();
        while (true) {
            spaces();
            if (pos >= (int)s.size() || s[pos] != '*') break;
            ++pos;
            p = multiply(p, factor());
        }
        return p;
    }
    Poly expression() {
        Poly p = term();
        while (true) {
            spaces();
            if (pos >= (int)s.size() || s[pos] == ')') break;
            char op = s[pos++];
            p = add(p, term(), op == '+' ? 1 : -1);
        }
        return p;
    }
public:
    vector<string> basicCalculatorIV(string expressionText, vector<string>& evalvars,
                                     vector<int>& evalints) {
        s = expressionText;
        pos = 0;
        values.clear();
        for (int i = 0; i < (int)evalvars.size(); ++i) values[evalvars[i]] = evalints[i];
        Poly p = expression();
        vector<pair<Key, int>> terms;
        for (const auto& x : p) if (x.second != 0) terms.push_back(x);
        sort(terms.begin(), terms.end(), [](const pair<Key,int>& a, const pair<Key,int>& b) {
            if (a.first.size() != b.first.size()) return a.first.size() > b.first.size();
            return a.first < b.first;
        });
        vector<string> answer;
        for (const auto& x : terms) {
            string t = to_string(x.second);
            for (const string& name : x.first) t += "*" + name;
            answer.push_back(t);
        }
        return answer;
    }
};
